class Solution:
    def checkXMatrix(self, grid: List[List[int]]) -> bool:
        n = len(grid)
        for i in range(n):
            for j in range(n):
                diag = i == j or i + j == n - 1
                if diag == (grid[i][j] == 0):
                    return False
        return True

c.cpp:
class Solution {
public:
    bool checkXMatrix(vector<vector<int>>& grid) {
        int n = grid.size();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                bool diag = (i == j) || (i + j == n - 1);
                if (diag == (grid[i][j] == 0)) return false;
            }
        return true;
    }
};

